 // guests tap a layout; clickers pick the highlighted one\n    if(readyOverlay.classList.contains('ready-active')){ readyStartBtn.click(); return; }\n    if(state === 'capturing' || printing || flowBusy) return;\n    if(tabSession.classList.contains('hidden')){\n      if(fromGuest) showToast('Finish Setup and open the Photo Session tab first.');\n      return;\n    }\n    if(!rawFolderKey()) return;\n    beginGuestFlow(true);\n  }\n  // Space / Enter / presenter-clicker keys (they send PageDown, PageUp or arrows).\n  const TRIGGER_KEYS = new Set([' ', 'Enter', 'PageDown', 'PageUp', 'ArrowRight', 'ArrowDown', 'ArrowLeft', 'ArrowUp', 'b', 'B']);\n  function onTriggerKey(e){\n    if(!TRIGGER_KEYS.has(e.key)) return;\n    const t = e.target;\n    const tag = t && t.tagName;\n    if(tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT' || (t && t.isContentEditable)) return;\n    // While guests are choosing a layout, arrows / clicker move the highlight.\n    if(pickOpen && (e.key === 'ArrowRight' || e.key === 'ArrowDown' || e.key === 'PageDown')){ e.preventDefault(); movePick(1); return; }\n    if(pickOpen && (e.key === 'ArrowLeft' || e.key === 'ArrowUp' || e.key === 'PageUp')){ e.preventDefault(); movePick(-1); return; }\n    if(e.key === 'ArrowLeft' || e.key === 'ArrowUp') return;\n    if(tag === 'BUTTON' && !pickOpen) return;\n    e.preventDefault();\n    boothTrigger(false);\n  }\n  document.addEventListener('keydown', onTriggerKey);\n\n  // ---- Start screen (before Setup) ----\n  const startScreen = document.getElementById('startScreen');\n  function refreshStartScreen(){\n    const pb = window.__PB || {};\n    const ev = (labelInput.value || '').trim() || (pb.type === 'rental' && pb.folderKey ? pb.folderKey : '');\n    document.getElementById('ssEvent').textContent = ev;\n    document.getElementById('ssDate').textContent = currentDateLabel() || (pb.type === 'trial' ? 'TRIAL' : '');\n    document.getElementById('ssStatus').textContent = isTraditional() ? 'Ready · Traditional booth' : 'Ready';\n  }\n  function leaveStartScreen(){\n    if(startScreen.classList.contains('gone')) return;\n    startScreen.classList.add('leaving', 'gone');\n    setTimeout(() => { startScreen.style.display = 'none'; }, 380);\n  }\n  startScreen.addEventListener('click', leaveStartScreen);\n  startScreen.addEventListener('keydown', (e) => { if(e.key === 'Enter' || e.key === ' '){ e.preventDefault(); e.stopPropagation(); leaveStartScreen(); } });\n  labelInput.addEventListener('input', () => { refreshStartScreen(); guestRender(); });\n\n  // =====================================================================\n  // Filters, photo review, welcome screen, guests choose the layout, GIF,\n  // themes and the saved setup. (Plain `var`s so earlier code can safely\n  // call these helpers during start-up.)\n  // =====================================================================\n  var filterKey = 'none';      // none | bw | sepia | warm | cool\n  var softSkin = false;\n  var gifOn = true;\n  var welcomeOn = true;\n  var welcomeMsg = '';\n  var reviewEach = true;       // show each photo during the pause between shots\n  var resultReviewSec = 0;     // 0 = finished photo stays until the next tap\n  var guestPickOn = false;\n  var guestLayoutSet = [];     // extra layouts guests may pick (besides setupLayout)\n  var themeId = null;\n\n  // ---- Filters ----\n  // Live view uses a CSS filter (instant, works everywhere); the photo itself\n  // is processed pixel by pixel, which also works on older iPads.\n  var FILTERS = {\n    none:  '',\n    bw:    'grayscale(1) contrast(1.08)',\n    sepia: 'sepia(.85) contrast(1.05) brightness(1.03)',\n    warm:  'sepia(.2) saturate(1.18) brightness(1.04)',\n    cool:  'saturate(.92) brightness(1.05) hue-rotate(10deg)'\n  };\n  function liveFilterCss(){\n    var f = FILTERS[filterKey] || '';\n    if(softSkin) f += ' brightness(1.04) contrast(.94)';\n    return f.trim();\n  }\n  function applyLiveFilter(){\n    video.